// Turns raw HTML into what the model needs: title, description, headings and readable text.
const html = String($input.first().json.html ?? '');

const entities = {
  nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", ndash: '-', mdash: '-',
  lsquo: "'", rsquo: "'", ldquo: '"', rdquo: '"', hellip: '...', copy: '(c)', reg: '(R)', trade: '(TM)',
};
const char = (code, fallback) => {
  try { return String.fromCodePoint(code); } catch { return fallback; }
};
const decode = (s) => s
  .replace(/&#x([0-9a-f]+);/gi, (m, hex) => char(parseInt(hex, 16), m))
  .replace(/&#(\d+);/g, (m, dec) => char(Number(dec), m))
  .replace(/&([a-z]+);/gi, (m, name) => entities[name.toLowerCase()] ?? m);
const clean = (s) => decode(s.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const first = (re) => {
  const m = html.match(re);
  return m ? clean(m[1]) : '';
};

const title = first(/<title[^>]*>([\s\S]*?)<\/title>/i);
const description =
  first(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i) ||
  first(/<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i);
const headings = [...html.matchAll(/<h([1-3])[^>]*>([\s\S]*?)<\/h\1>/gi)]
  .map((m) => `H${m[1]}: ${clean(m[2])}`)
  .filter((h) => h.length > 4)
  .slice(0, 40);
const text = clean(
  html
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg|nav|footer|form)[^>]*>[\s\S]*?<\/\1>/gi, ' ')
).slice(0, 8000);

if (!text) {
  throw new Error('That page has no readable text. It may need JavaScript to render, or it blocked the request.');
}

return [{ json: { url: $('Webhook').first().json.body.url, title, description, headings, text } }];

// Picks the model and writes the request for Ollama. Edit the prompt and fields here.
const page = $input.first().json;
const requested = $('Webhook').first().json.body.model;
const installed = ($('List models').first().json.models ?? []).map((m) => m.name);
const model = requested || installed.find((name) => !/embed/i.test(name));

if (!model) {
  throw new Error('No chat model found. Pull one first, for example: ./lab.sh pull qwen3.5:4b');
}

const list = (description) => ({ type: 'array', items: { type: 'string' }, description });
const schema = {
  type: 'object',
  properties: {
    summary: { type: 'string', description: 'Two sentences on what the page offers and to whom' },
    page_type: {
      type: 'string',
      enum: ['homepage', 'product page', 'pricing page', 'comparison page', 'landing page', 'blog post', 'guide', 'documentation', 'other'],
    },
    search_intent: { type: 'string', enum: ['informational', 'commercial', 'transactional', 'navigational'] },
    funnel_stage: { type: 'string', enum: ['awareness', 'consideration', 'decision'] },
    target_audience: { type: 'string' },
    primary_topic: { type: 'string' },
    keywords: list('5 to 10 search phrases this page is trying to rank for'),
    buying_signals: list('What on the page suggests the reader is evaluating a purchase (pricing, comparisons, demos, trials)'),
    content_gaps: list('Questions a reader would still have after this page'),
  },
  required: ['summary', 'page_type', 'search_intent', 'funnel_stage', 'target_audience', 'primary_topic', 'keywords', 'buying_signals', 'content_gaps'],
};

const pageText = [
  `URL: ${page.url}`,
  `Title: ${page.title}`,
  `Meta description: ${page.description}`,
  `Headings:\n${page.headings.join('\n')}`,
  `Page text:\n${page.text}`,
].join('\n\n');

return [{
  json: {
    request: {
      model,
      stream: false,
      think: false,
      format: schema,
      options: { temperature: 0.2, num_ctx: 8192 },
      messages: [
        {
          role: 'system',
          content: 'You are an SEO and content strategist. Analyze the web page you are given and describe its search intent, audience and keywords. Base every answer on the page itself. Reply with JSON only.',
        },
        { role: 'user', content: pageText },
      ],
    },
  },
}];

// Turns the model's reply into the webhook's answer.
const page = $('Extract page text').first().json;
const reply = $input.first().json;
const content = reply.message?.content ?? '';

let analysis;
try {
  analysis = JSON.parse(content);
} catch {
  analysis = {
    error: "The model's answer wasn't valid JSON. Run it again, or try a larger model.",
    raw_answer: content,
  };
}

return [{
  json: {
    url: page.url,
    title: page.title,
    model: reply.model,
    seconds: Math.round((reply.total_duration ?? 0) / 1e9),
    ...analysis,
  },
}];
